import{_ as a}from"./chunks/analytics_apple.i3PNHCzB.js";import{_ as o,H as n,c as r,b as i,a2 as s,K as l}from"./chunks/framework.BEqfOpL-.js";const p="/images/analytics_apple_episodes.webp",d="/images/analytics_apple_audience.webp",b=JSON.parse(`{"title":"Apple Podcasts analytics","description":"Use Apple Podcasts analytics to understand plays, listening time, followers and how people move through individual episodes. These measurements describe listening on Apple Podcasts; they are not your show's downloads across every app.","frontmatter":{},"headers":[],"relativePath":"features/apple-podcasts-analytics.md","filePath":"features/apple-podcasts-analytics.md"}`),h={name:"features/apple-podcasts-analytics.md"};function c(u,e,g,m,w,y){const t=n("HelpWalkthrough");return i(),r("div",null,[e[0]||(e[0]=s('<h1 id="apple-podcasts-analytics" tabindex="-1">Apple Podcasts analytics <a class="header-anchor" href="#apple-podcasts-analytics" aria-label="Permalink to &quot;Apple Podcasts analytics&quot;">​</a></h1><p>Use Apple Podcasts analytics to understand plays, listening time, followers and how people move through individual episodes. These measurements describe listening on Apple Podcasts; they are not your show&#39;s downloads across every app.</p><p><strong>To access:</strong> choose your podcast → <strong>Analytics → Apple Podcasts</strong>. If you see connection steps instead of reports, follow <a href="/features/analytics-connections.html#apple-podcasts-connect">Connect Apple Podcasts</a>. You can read the reports on every PodSEO plan.</p><p><a href="/images/analytics_apple.webp" title="Open screenshot at full size"><img src="'+a+'" alt="Apple Podcasts overview and reporting period"></a></p><h2 id="read-the-overview" tabindex="-1">Read the Overview <a class="header-anchor" href="#read-the-overview" aria-label="Permalink to &quot;Read the Overview&quot;">​</a></h2><p>The <strong>30</strong>, <strong>90</strong> and <strong>365 days</strong> selector changes plays, hours listened and the relevant follower period. It does not turn every card into a report for the same dates: <strong>Listeners, last 60 days</strong> keeps Apple&#39;s own window. Read each card&#39;s dates and the number of days reported.</p><ul><li><strong>Plays</strong> counts episode playbacks, using Apple&#39;s measurement.</li><li><strong>Hours listened</strong> describes time spent listening.</li><li><strong>Listeners</strong> counts people within Apple&#39;s reporting window. Do not add daily or monthly listener counts: the same person can appear in several windows.</li><li><strong>Engaged listeners</strong> listened to at least 20 minutes or 40% of an episode.</li></ul><p>The daily plays chart leaves gaps where Apple reported no measurement. Followers shows the total as of its stated date and the gained/lost figures for its period. <strong>Time listened: followers and everyone else</strong> compares shares of listening time, not shares of unique people.</p><p>Expand <strong>Month by month</strong> to see monthly plays, listeners, engaged listeners and hours, plus the available all-time totals. Those all-time figures cover Apple&#39;s records, not necessarily the entire life of your podcast.</p><h2 id="compare-episode-launches" tabindex="-1">Compare episode launches <a class="header-anchor" href="#compare-episode-launches" aria-label="Permalink to &quot;Compare episode launches&quot;">​</a></h2><p>Open <strong>Episodes</strong>. The table combines all-time episode measurements with separately labelled launch measurements:</p><table tabindex="0"><thead><tr><th>Column</th><th>How to use it</th></tr></thead><tbody><tr><td><strong>Plays</strong>, <strong>Listeners</strong></td><td>All-time episode counts as of the stated read date</td></tr><tr><td><strong>First 7 days / First 30 days</strong></td><td>Plays from release day; a newer episode can show progress such as “day 3 of 7”</td></tr><tr><td><strong>Launch</strong>, when available</td><td>Unique listeners over the displayed launch interval, compared with a typical episode at the same age</td></tr><tr><td><strong>Engaged</strong></td><td>Share of the episode&#39;s listeners who meet Apple&#39;s engagement definition</td></tr><tr><td><strong>Avg. listened</strong></td><td>Listening time per play as a share of the episode&#39;s duration; this differs from the engaged share</td></tr></tbody></table><p><a href="/images/analytics_apple_episodes.webp" title="Open screenshot at full size"><img src="'+p+'" alt="Apple Podcasts episode table and launch comparisons"></a></p><p>Compare complete first-week windows with complete first-week windows. The page explains where first-days coverage begins; an older episode can show “–” because its launch predates that coverage.</p><h2 id="open-an-episode-s-complete-report" tabindex="-1">Open an episode&#39;s complete report <a class="header-anchor" href="#open-an-episode-s-complete-report" aria-label="Permalink to &quot;Open an episode&#39;s complete report&quot;">​</a></h2><ol><li>In <strong>Episodes</strong>, click an episode title or <strong>View report</strong>.</li><li>Read <strong>Inside the episode</strong> to see the listening curve along elapsed episode time.</li><li>Use <strong>Daily listening</strong> to explore plays or listening time by date.</li><li>Use <strong>How the episode has grown</strong> to inspect cumulative snapshots. Never add these snapshots together.</li><li>Expand <strong>All episode measurements</strong> for the reported totals, or inspect the available country breakdown.</li></ol>',16)),l(t,{src:"/walkthroughs/apple-episode.webp",poster:"/images/analytics_apple_episode_detail.webp",alt:"Open an Apple episode from the episode list and inspect its listening report",duration:20200}),e[1]||(e[1]=s('<p>Each chart has <strong>Reported values</strong> and <strong>Export CSV</strong> when data is available. A metric selector changes the measurement inside that report; it does not change the period of unrelated cards. <strong>Close report</strong> collapses the detail back into the episode table.</p><p>To compare its Apple curve with Spotify, use <strong>Find this episode across your connected platforms</strong>. See <a href="/features/analytics.html#compare-listening-curves-and-select-a-passage">Compare episode listening curves</a>.</p><h2 id="understand-the-audience-view" tabindex="-1">Understand the Audience view <a class="header-anchor" href="#understand-the-audience-view" aria-label="Permalink to &quot;Understand the Audience view&quot;">​</a></h2><p><strong>Audience</strong> shows countries, top cities and follower comparisons when Apple provides them. A map or share is shown only when a suitable total is available; otherwise read the reported counts and ordering without assuming a percentage. Each card keeps its own measurement and reporting window. Where a country map is available, expand <strong>All reported countries</strong> and select a country to highlight it and read its reported share.</p><p><a href="/images/analytics_apple_audience.webp" title="Open screenshot at full size"><img src="'+d+'" alt="Apple audience reports with their own dates and measurement labels"></a></p><p><strong>Audience over time</strong>, when available, adds historical reports. Choose the displayed location or measurement and use <strong>Show trend</strong> where offered. These trends and the latest audience snapshot answer different questions.</p><h2 id="missing-values-and-delayed-updates" tabindex="-1">Missing values and delayed updates <a class="header-anchor" href="#missing-values-and-delayed-updates" aria-label="Permalink to &quot;Missing values and delayed updates&quot;">​</a></h2><p>Open <strong>More</strong> for Apple&#39;s reporting notes. Apple can withhold numbers below five listeners; PodSEO shows unavailable values as “–”, not zero. Apple keeps a limited daily history, while the longer PodSEO views build up as measurements become available. Recent values can be revised.</p><p>A <strong>delayed</strong> warning means the latest available reports remain visible. Check their dates before treating a quiet or missing day as a change in audience. If access was removed, reconnect through the source&#39;s instructions; <a href="/features/connections.html">Connections</a> manages existing access. Why these reports need a show claimed in Apple Podcasts Connect: <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p><h2 id="a-useful-review-routine" tabindex="-1">A useful review routine <a class="header-anchor" href="#a-useful-review-routine" aria-label="Permalink to &quot;A useful review routine&quot;">​</a></h2><p>Start with plays and hours in Overview, compare episodes at the same age, then open the listening curve for an episode that differs from the others. Use the curve to identify a passage worth reviewing in your audio. A dip alone does not explain why it happened; compare it with the opening, chapter or ad break before changing your format.</p>',11))])}const _=o(h,[["render",c]]);export{b as __pageData,_ as default};
